const seller = $json;
const money = (amount, currency) => new Intl.NumberFormat('es-CO', { style: 'currency', currency, minimumFractionDigits: 0 }).format(amount);
const count = seller.orders.length;

const rows = seller.orders
  .map((o) => `<tr><td>#${o.id.slice(0, 8)}</td><td>${o.buyer}</td><td align="right">${money(o.total, o.currency)}</td><td>${o.transfer_number ?? '—'}</td><td align="center"><b>${o.hours_left} h</b></td></tr>`)
  .join('');

const subject = `⏰ ${count} ${count === 1 ? 'comprobante vence' : 'comprobantes vencen'} en menos de 24 h`;
const html = `<p>Hola ${seller.seller_name},</p>
<p>Estos pedidos tienen el comprobante de pago <b>sin revisar</b>. Si no los apruebas o rechazas a tiempo, Libra los vence automáticamente y el comprador pierde su compra.</p>
<table cellpadding="6" style="border-collapse:collapse" border="1">
<tr><th align="left">Pedido</th><th align="left">Comprador</th><th align="right">Total</th><th align="left">Ref.</th><th>Vence en</th></tr>${rows}
</table>
<p>Revísalos en Studio.</p>
<p style="color:#666">Recordatorio automático de Libra.</p>`;

return { json: { to: seller.seller_email, subject, html, orders: count } };
